class Rect:
    def __init__(self, w, h):
        self.w = w
        self.h = h
    def area(self):
        return self.w * self.h
    def perimeter(self):
        return 2 * (self.w + self.h)
r = Rect(4, 6)
print(r.area())
print(r.perimeter())

class Counter:
    def __init__(self, start):
        self.value = start
    def step(self, k):
        self.value += k
        return self.value
c = Counter(10)
print(c.step(3))
print(c.step(-5))
print(c.value)

class Student:
    def __init__(self, name, scores):
        self.name = name
        self.scores = scores
    def avg(self):
        return sum(self.scores) / len(self.scores)
s = Student('小明', [80, 90, 85])
print(s.name, '{:.1f}'.format(s.avg()))

