class Text:
    def __init__(self, s):
        self.s = s
    def words(self):
        return self.s.split()
    def longest(self):
        best = ''
        for w in self.words():
            if len(w) > len(best):
                best = w
        return best
t = Text('I love Python programming')
print(len(t.words()), t.longest())

