class Queue:
    def __init__(self):
        self.data = []
    def push(self, x):
        self.data.append(x)
    def pop(self):
        return self.data.pop(0)
    def size(self):
        return len(self.data)
q = Queue()
for i in range(1, 5):
    q.push(i * 10)
print(q.pop(), q.pop())
print(q.size())

class Score:
    def __init__(self, v):
        self.v = v
    def level(self):
        if self.v >= 90:
            return '优'
        elif self.v >= 75:
            return '良'
        elif self.v >= 60:
            return '中'
        return '差'
for v in [95, 60, 74, 30]:
    print(Score(v).level(), end=' ')

