class Person:
    def __init__(self, name):
        self.name = name
    def intro(self):
        return '我是' + self.name
class Student(Person):
    def __init__(self, name, school):
        super().__init__(name)
        self.school = school
    def intro(self):
        return Person.intro(self) + '，就读于' + self.school
s = Student('小李', '海大')
print(s.intro())

class Shape:
    def area(self):
        return 0
class Square(Shape):
    def __init__(self, a):
        self.a = a
    def area(self):
        return self.a * self.a
class Tri(Shape):
    def __init__(self, b, h):
        self.b = b
        self.h = h
    def area(self):
        return self.b * self.h / 2
for s in [Square(3), Tri(4, 5), Shape()]:
    print(s.area())
